import{_ as i,o as a,a as l,b as e}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul Tiling类","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling"},{"text":"Matmul Tiling类使用说明","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling_usage"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling_usage.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling_usage.md","outlineHeaders":[{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"}],"lastUpdated":1785997882000}'),n={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling_usage.md"};function d(m,t,g,o,r,u){return a(),l("div",null,[...t[0]||(t[0]=[e(`<div><article class="markdown-body"><h1>Matmul Tiling类使用说明</h1><p>Ascend C提供一组Matmul Tiling API，方便用户获取<a href="../Matmul_Kernel/Matmul_usage.html#li5878185413338">Matmul kernel计算</a>时所需的Tiling参数。用户只需要传入A/B/C矩阵的Position位置、Format格式和DType数据类型等信息，调用API接口，即可获取到<a href="../Matmul_Kernel/Init.html">Init</a>中TCubeTiling结构体中的相关参数。</p><p>Matmul Tiling API分为Matmul单核Tiling接口、多核Tiling接口和BatchMatmul Tiling接口，分别用于Matmul单核计算、多核计算和BatchMatmul计算场景。获取Tiling参数的流程如下：</p><ol><li>创建一个单核Tiling对象，或多核Tiling对象，或BatchMatmul Tiling对象。</li><li>设置A、B、C、Bias的参数类型信息；M、N、Ka、Kb形状信息等。</li><li>调用<a href="GetTiling.html">GetTiling</a>接口，获取Tiling信息。</li></ol><p>使用Matmul单核Tiling接口、多核Tiling接口和BatchMatmul Tiling接口获取Tiling参数的样例如下：</p><ul><li><p>Matmul单核Tiling</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
matmul_tiling::MatmulApiTiling tiling(ascendcPlatform);
// 设置A、B、C、Bias矩阵Position、Format、DType信息
tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
tiling.SetShape(1024, 1024, 1024);    // 设置单核计算的M、N、K大小
tiling.SetOrgShape(1024, 1024, 1024); // 设置原始输入M、N、K大小，单核Tiling与SetShape一致。
                                      // 若Ka,Kb不等长时，设置tiling.SetOrgShape(1024,1024, 1024, 1280)
tiling.EnableBias(true);              // 设置matmul计算包含bias
tiling.SetBufferSpace(-1, -1, -1);    // 设定允许使用的空间，缺省使用该AI处理器所有空间
optiling::TCubeTiling tilingData;
int64_t ret = tiling.GetTiling(tilingData); // if ret = -1, get tiling failed
</code></pre></div></li><li><p>Matmul多核Tiling</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
matmul_tiling::MultiCoreMatmulTiling tiling(ascendcPlatform);
tiling.SetDim(1); // 设置参与计算的核数为1
tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
tiling.SetShape(1024, 1024, 1024);
tiling.SetSingleShape(1024, 1024, 1024);
tiling.SetOrgShape(1024, 1024, 1024);
tiling.EnableBias(true);
tiling.SetBufferSpace(-1, -1, -1); // 设定允许使用的空间，缺省使用该AI处理器所有空间
optiling::TCubeTiling tilingData;
int64_t ret = tiling.GetTiling(tilingData); // if ret = -1, get tiling failed
</code></pre></div></li><li><p>BatchMatmul Tiling</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
matmul_tiling::BatchMatmulTiling bmmTiling(ascendcPlatform);

bmmTiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
bmmTiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);
bmmTiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
bmmTiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
bmmTiling.EnableBias(true);
bmmTiling.SetShape(64, 48, 32);
bmmTiling.SetSingleShape(64, 48, 32);
bmmTiling.SetOrgShape(64, 48, 32);
// Layout类型为NORMAL时,通过SetBatchInfoForNormal设置A、B、C矩阵的Layout轴信息
bmmTiling.SetBatchInfoForNormal(2, 2, 64, 48, 32);
// Layout类型为BSNGD、SBNGD、BNGS1S2时,通过SetALayout、SetBLayout、SetCLayout设置A、B、C矩阵的Layout轴信息
// bmmTiling.SetALayout(3, 64, 2, 2, 32);
// bmmTiling.SetBLayout(3, 32, 2, 2, 48);
// bmmTiling.SetCLayout(3, 64, 2, 2, 48);
bmmTiling.SetBatchNum(2);
bmmTiling.SetBufferSpace(-1, -1, -1); // 设定允许使用的空间，缺省使用该AI处理器所有空间
optiling::TCubeTiling tilingData;
int64_t ret = bmmTiling.GetTiling(tilingData); // if ret = -1, get tiling failed
</code></pre></div></li></ul><p>接口列表如下：</p><p><strong>表1</strong> MatmulApiTiling/MultiCoreMatmulTiling/BatchMatmulTiling共有接口列表</p><table><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td>SetAType</td><td>设置A矩阵的位置，数据格式，数据类型，是否转置等信息。</td></tr><tr><td>SetBType</td><td>设置B矩阵的位置，数据格式，数据类型，是否转置等信息。</td></tr><tr><td>SetCType</td><td>设置C矩阵的位置，数据格式，数据类型等信息。</td></tr><tr><td>SetDequantType</td><td>设置反量化的模式。</td></tr><tr><td>SetBiasType</td><td>设置Bias的位置，数据格式，数据类型等信息。</td></tr><tr><td>SetShape</td><td>设置Matmul单次计算的形状singleM、singleN、singleK，单位为元素个数。</td></tr><tr><td>SetOrgShape</td><td>设置Matmul计算时的原始完整的形状M、N、Ka、Kb，单位为元素个数。</td></tr><tr><td>SetALayout</td><td>设置A矩阵的Layout轴信息。</td></tr><tr><td>SetBLayout</td><td>设置B矩阵的Layout轴信息。</td></tr><tr><td>SetCLayout</td><td>设置C矩阵的Layout轴信息。</td></tr><tr><td>SetBatchInfoForNormal</td><td>设置A/B矩阵的M/N/K轴信息，以及A/B矩阵各自的Batch数。</td></tr><tr><td>SetBatchNum</td><td>设置多Batch计算的最大Batch数。</td></tr><tr><td>EnableBias</td><td>设置Bias是否参与运算。</td></tr><tr><td>SetBias</td><td>设置Bias是否参与运算。建议使用EnableBias接口。</td></tr><tr><td>SetFixSplit</td><td>设置固定的baseM、baseN、baseK，单位为元素个数。</td></tr><tr><td>SetBufferSpace</td><td>设置Matmul计算时可用的L1/L0C/UB空间大小，单位为字节。</td></tr><tr><td>SetTraverse</td><td>设置遍历方式，M轴优先还是N轴优先。</td></tr><tr><td>SetMadType</td><td>设置是否开启HF32模式。当前版本暂不支持。</td></tr><tr><td>SetSplitRange</td><td>设置baseM/baseN/baseK的最大值和最小值。</td></tr><tr><td>SetMatmulConfigParams</td><td>自定义设置MatmulConfig参数。</td></tr><tr><td>SetDoubleBuffer</td><td>设置A/B/C/Bias是否开启double buffer功能，以及是否需要做ND2NZ或者NZ2ND的转换。该接口为预留接口，当前版本暂不支持。</td></tr><tr><td>GetBaseM</td><td>获取baseM值。</td></tr><tr><td>GetBaseN</td><td>获取baseN值。</td></tr><tr><td>GetBaseK</td><td>获取baseK值。</td></tr><tr><td>GetTiling</td><td>获取Tiling参数。</td></tr></tbody></table><p><strong>表2</strong> MultiCoreMatmulTiling其他接口</p><table><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td>SetDim</td><td>设置多核Matmul时，可以参与运算的核数。</td></tr><tr><td>SetSingleRange</td><td>设置singleCoreM/singleCoreN/singleCoreK的最大值与最小值，单位为元素个数。</td></tr><tr><td>SetSingleShape</td><td>设置Matmul单核计算的形状singleCoreM、singleCoreN、singleCoreK，单位为元素个数。</td></tr><tr><td>GetSingleShape</td><td>获取计算后的singleCoreM/singleCoreN/singleCoreK。</td></tr><tr><td>SetAlignSplit</td><td>设置多核切分时singleCoreM/singleCoreN/singleCoreK的对齐值。</td></tr><tr><td>GetCoreNum</td><td>获得多核切分后，使用的numBlocks。</td></tr><tr><td>SetSplitK</td><td>多核场景，开启切K轴。建议使用EnableMultiCoreSplitK接口。</td></tr><tr><td>EnableMultiCoreSplitK</td><td>多核场景，开启切K轴。</td></tr></tbody></table><p><strong>表3</strong> BatchMatmulTiling其他接口</p><table><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td>GetCoreNum</td><td>获得多核切分后，使用的numBlocks。</td></tr></tbody></table><h2 id="需要包含的头文件">需要包含的头文件<a class="header-anchor" href="#需要包含的头文件">​</a></h2><ul><li><p>Matmul单核Tiling</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/matmul/matmul_tiling.h&quot;
</code></pre></div></li><li><p>Matmul多核Tiling</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/matmul/bmm_tiling.h&quot;
</code></pre></div></li><li><p>BatchMatmul Tiling</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/matmul/bmm_tiling.h&quot;
</code></pre></div></li></ul></article></div>`,1)])])}const h=i(n,[["render",d]]);export{p as __pageData,h as default};
